A `TStringList` splits the text into lines, and it is freed in a `try...finally`. `Create` goes **before** `try`: if the constructor fails there is nothing to free, and once it has succeeded `finally` frees the list whatever happens inside.

```delphi
unit TextLines;

interface

function CountNonEmptyLines(const AText: string): Integer;

implementation

uses
  System.Classes, System.SysUtils;

function CountNonEmptyLines(const AText: string): Integer;
var
  Lines: TStringList;
  Line: string;
begin
  Result := 0;
  Lines := TStringList.Create;
  try
    Lines.Text := AText;
    for Line in Lines do
      if Trim(Line) <> '' then
        Inc(Result);
  finally
    Lines.Free;
  end;
end;

end.
```

`TList<T>.Sort` takes an `IComparer<T>`, and `TComparer<T>.Construct` (System.Generics.Defaults) builds one from an anonymous function. `CompareText` compares two strings ignoring case.

```delphi
unit PeopleSort;

interface

uses
  System.Generics.Collections;

type
  TPerson = record
    Name: string;
    Age: Integer;
  end;

procedure SortByName(const APeople: TList<TPerson>);

implementation

uses
  System.Generics.Defaults, System.SysUtils;

procedure SortByName(const APeople: TList<TPerson>);
begin
  APeople.Sort(TComparer<TPerson>.Construct(
    function(const ALeft, ARight: TPerson): Integer
    begin
      Result := CompareText(ALeft.Name, ARight.Name);
    end));
end;

end.
```

`Copy(S, 1, 3)` does it and is safe on shorter strings: `Copy` clips to what is there. Mind where counting starts: `Copy`, `Pos` and `S[i]` count from **1**, while the string helper methods count from **0** - `'ABCDEF'.Substring(1, 3)` is `'BCD'` and `'ABCDEF'.IndexOf('A')` is 0. Do not mix the two styles in one expression.

```delphi
unit CodePrefix;

interface

function Prefix3(const ACode: string): string;

implementation

function Prefix3(const ACode: string): string;
begin
  // Copy counts from 1 and clips: a shorter code comes back whole
  Result := Copy(ACode, 1, 3);
end;

end.
```

The class derives from `TInterfacedObject`, which counts references: hold it through `ILogger` variables and never call `Free` on it - when the last reference goes away, it frees itself. Keeping the class in the implementation section and handing out only the interface means nobody can mix an object variable (and a `Free`) with interface references.

```delphi
unit AppLogger;

interface

type
  ILogger = interface
    ['{6F1C2B3A-8D4E-4F5A-9B7C-1D2E3F4A5B6C}']
    procedure Log(const AText: string);
    function Count: Integer;
  end;

function NewMemoryLogger: ILogger;

implementation

uses
  System.Classes;

type
  TMemoryLogger = class(TInterfacedObject, ILogger)
  private
    FLines: TStringList;
  public
    constructor Create;
    destructor Destroy; override;
    procedure Log(const AText: string);
    function Count: Integer;
  end;

constructor TMemoryLogger.Create;
begin
  inherited Create;
  FLines := TStringList.Create;
end;

destructor TMemoryLogger.Destroy;
begin
  FLines.Free;
  inherited Destroy;
end;

procedure TMemoryLogger.Log(const AText: string);
begin
  FLines.Add(AText);
end;

function TMemoryLogger.Count: Integer;
begin
  Result := FLines.Count;
end;

function NewMemoryLogger: ILogger;
begin
  Result := TMemoryLogger.Create;
end;

end.
```

Each class needs the other, so `TCustomer` is declared ahead with a forward declaration (`TCustomer = class;`). The forward declaration and the full one must be in the **same** `type` section. `TObjectList<TOrder>` owns the orders, so freeing the customer frees them too.

```delphi
unit Shop;

interface

uses
  System.Generics.Collections;

type
  TCustomer = class; // forward declaration: completed below, in this same type section

  TOrder = class
  private
    FCustomer: TCustomer;
  public
    constructor Create(const ACustomer: TCustomer);
    property Customer: TCustomer read FCustomer;
  end;

  TCustomer = class
  private
    FName: string;
    FOrders: TObjectList<TOrder>;
  public
    constructor Create(const AName: string);
    destructor Destroy; override;
    function AddOrder: TOrder;
    property Name: string read FName;
    property Orders: TObjectList<TOrder> read FOrders;
  end;

implementation

constructor TOrder.Create(const ACustomer: TCustomer);
begin
  inherited Create;
  FCustomer := ACustomer;
end;

constructor TCustomer.Create(const AName: string);
begin
  inherited Create;
  FName := AName;
  FOrders := TObjectList<TOrder>.Create(True); // owns its orders
end;

destructor TCustomer.Destroy;
begin
  FOrders.Free;
  inherited Destroy;
end;

function TCustomer.AddOrder: TOrder;
begin
  Result := TOrder.Create(Self);
  FOrders.Add(Result);
end;

end.
```

`case` only accepts ordinal values (integers, characters, enumerations), and a string is not one. Turn the name into an index first: `IndexText` (System.StrUtils) returns its position in the list ignoring case, or -1, and the `case` branches on that integer.

```delphi
unit ColorCodes;

interface

function ColorCode(const AName: string): Integer;

implementation

uses
  System.StrUtils;

function ColorCode(const AName: string): Integer;
begin
  // case needs an ordinal value: turn the name into its index first
